    if (this.token) {
      headers["x-key"] = this.token;
    }

    const response = await gatewayFetch(url, {
      headers,
      signal: AbortSignal.timeout(10000),
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    return response.json() as Promise<SurgeRequestsData>;
  }

  stop() {
